function pageContent(config,pathname){
 const body=config.sections.map(([eyebrow,title,html])=>section(eyebrow,title,html)).join('');
 const guide=practicalGuides[pathname];
 const guideHtml=guide?section('ПРАКТИЧНИЙ ЧЕКЛІСТ',guide[0],`<ol>${guide[1].map(item=>`<li>${e(item)}</li>`).join('')}</ol>`):'';
 return `<section class="seo-hero"><div class="seo-wrap seo-hero-grid"><div class="seo-hero-copy"><p class="eyebrow">${e(config.eyebrow||'VDALO / ДЛЯ ГОТЕЛЮ')}</p><h1>${e(config.h1)}</h1><p class="seo-lead">${e(config.lead)}</p>${config.status?`<p class="seo-status-pill"><span>СТАТУС</span>${e(config.status)}</p>`:''}<div class="seo-hero-actions">${auditButton(config.heroCta||'Обговорити мій процес',config.heroKind||'audit',config.h1)}<a class="seo-secondary" href="${e(config.heroSecondaryHref||'/solutions')}">${e(config.heroSecondary||'Переглянути можливості')} <span aria-hidden="true">↗</span></a></div></div><figure class="seo-hero-visual${config.heroPortrait?' seo-hero-portrait':''}" style="--hero-position:${e(config.heroPosition||'center')}"><img src="/assets/${e(config.heroImage)}" width="${e(config.heroWidth||1536)}" height="${e(config.heroHeight||1024)}" alt="${e(config.heroAlt)}" title="${e(config.heroAlt)}" fetchpriority="high"></figure></div></section><div class="seo-wrap">${body}${articleBridges[pathname]?articleBridge(pathname):''}${config.extra||''}${guideHtml}${relatedPages(pathname)}</div>`;
}

export function seoRoutes(){return [...Object.keys(pages),'/partners'];}
export function renderSeoPage(pathname){
 if(pathname==='/partners')return renderPartnersPage();
 const config=pages[pathname]; if(!config)return null;
 const canonical=`${origin}${pathname}`;
 const type=pathname==='/solutions'?'CollectionPage':'WebPage';
 const graph=JSON.stringify({'@context':'https://schema.org','@type':type,'name':config.title,'description':config.description,'url':canonical,'inLanguage':'uk','isPartOf':{'@type':'WebSite','name':'VDALO','url':origin}}).replace(/</g,'\\u003c');
 let html=renderPage({origin,full:true});
 html=html.replace(/<main id="main">[\s\S]*?<\/main>/,`<main id="main" class="seo-page">${pageContent(config,pathname)}</main>`);
 html=html.replace(/<title>[\s\S]*?<\/title>/,`<title>${e(config.title)}</title>`)
  .replace(/<meta name="description" content="[^"]*">/,`<meta name="description" content="${e(config.description)}">`)
  .replace(/<meta property="og:title" content="[^"]*">/,`<meta property="og:title" content="${e(config.title)}">`)
  .replace(/<meta property="og:description" content="[^"]*">/,`<meta property="og:description" content="${e(config.description)}">`)
  .replace(/<link rel="canonical" href="[^"]*">/,`<link rel="canonical" href="${canonical}">`)
  .replace(/<meta property="og:url" content="[^"]*">/,`<meta property="og:url" content="${canonical}">`)
  .replace(/<script type="application\/ld\+json">[\s\S]*?<\/script>/,`<script type="application/ld+json">${graph}</script>`)
  .replace('</head>',`<link rel="stylesheet" href="/seo-pages.css?v=${assetVersion('seo-pages.css')}"></head>`)
  .replace(/<nav id="navigation"[\s\S]*?<\/nav>/,nav=>nav.replace(/href="#([^"]+)"/g,'href="/#$1"'))
  .replace(/<footer[\s\S]*?<\/footer>/,footer=>footer.replace(/href="#([^"]+)"/g,'href="/#$1"'));
 if(pathname==='/integrations')html=html.replace('</main>',`${partnerIntegrationBridge}</main>`);
 return html;
}
